  Future<void> attemptSave() async {
    final canConnect = await ref.read(testNodeConnectionProvider)(
      context: context,
      cryptoCurrency: coin,
      nodeFormData: ref.read(nodeFormDataProvider),
    );

    bool? shouldSave;

    if (!canConnect && mounted) {
      await showDialog<dynamic>(
        context: context,
        useSafeArea: true,
        barrierDismissible: true,
        builder: (_) => isDesktop
            ? DesktopDialog(
                maxWidth: 440,
                maxHeight: 300,
                child: Column(
                  children: [
                    Padding(
                      padding: const EdgeInsets.only(top: 32),
                      child: Row(
                        children: [
                          const SizedBox(width: 32),
                          Text(
                            l10n.nodeUnreachableTitle,
                            style: STextStyles.desktopH3(context),
                          ),
                        ],
                      ),
                    ),
                    Expanded(
                      child: Padding(
                        padding: const EdgeInsets.only(
                          left: 32,
                          right: 32,
                          top: 16,
                          bottom: 32,
                        ),
                        child: Column(
                          children: [
                            const Spacer(),
                            Text(
                              l10n.nodeSaveAnyway,
                              style: STextStyles.desktopTextMedium(context),
                            ),
                            const Spacer(flex: 2),
                            Row(
                              children: [
                                Expanded(
                                  child: SecondaryButton(
                                    label: l10n.commonCancel,
                                    buttonHeight: isDesktop
                                        ? ButtonHeight.l
                                        : null,
                                    onPressed: () => Navigator.of(
                                      context,
                                      rootNavigator: true,
                                    ).pop(false),
                                  ),
                                ),
                                const SizedBox(width: 16),
                                Expanded(
                                  child: PrimaryButton(
                                    label: l10n.commonSave,
                                    buttonHeight: isDesktop
                                        ? ButtonHeight.l
                                        : null,
                                    onPressed: () => Navigator.of(
                                      context,
                                      rootNavigator: true,
                                    ).pop(true),
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                    ),
                  ],
                ),
              )
            : StackDialog(
                title: l10n.nodeUnreachableTitle,
                message: l10n.nodeSaveAnyway,
                leftButton: TextButton(
                  onPressed: () async {
                    Navigator.of(context).pop(false);
                  },
                  child: Text(
                    l10n.commonCancel,
                    style: STextStyles.button(context).copyWith(
                      color: Theme.of(context)
                          .extension<StackColors>()!
                          .accentColorDark,
                    ),
                  ),
                ),
                rightButton: TextButton(
                  onPressed: () async {
                    Navigator.of(context).pop(true);
                  },
                  style: Theme.of(context)
                      .extension<StackColors>()!
                      .getPrimaryEnabledButtonStyle(context),
                  child: Text(l10n.commonSave, style: STextStyles.button(context)),
                ),
              ),
      ).then((value) {
        if (value is bool && value) {
          shouldSave = true;
        } else {
          shouldSave = false;
        }
      });
    }

    if (!canConnect && !shouldSave!) {
      // return without saving
      return;
    }

    final formData = ref.read(nodeFormDataProvider);

    // strip unused path
    final String address = formData.host!;

    final torEnabled = formData.netOption?.allowsTor() ?? false;
    final plainEnabled = formData.netOption?.allowsClear() ?? false;

    switch (viewType) {
      case AddEditNodeViewType.add:
        final NodeModel node = NodeModel(
          host: address,
          port: formData.port!,
          name: formData.name!,
          id: const Uuid().v1(),
          useSSL: formData.useSSL!,
          coinName: coin.identifier,
          torEnabled: torEnabled,
          clearnetEnabled: plainEnabled,
          isPrimary: false,
        );

        await ref.read(nodeServiceChangeNotifierProvider).save(node, true);
        await _notifyWalletsOfUpdatedNode();
        if (mounted) {
          Navigator.of(context)
              .popUntil(ModalRoute.withName(widget.routeOnSuccessOrDelete));
        }
        break;
      case AddEditNodeViewType.edit:
        final NodeModel node = NodeModel(
          host: address,
          port: formData.port!,
          name: formData.name!,
          id: nodeId!,
          useSSL: formData.useSSL!,
          coinName: coin.identifier,
          torEnabled: torEnabled,
          clearnetEnabled: plainEnabled,
          isPrimary: formData.isPrimary ?? false,
        );

        await ref.read(nodeServiceChangeNotifierProvider).save(node, true);
        await _notifyWalletsOfUpdatedNode();
        if (mounted) {
          Navigator.of(context)
              .popUntil(ModalRoute.withName(widget.routeOnSuccessOrDelete));
        }
        break;
    }
  }

  Future<void> _notifyWalletsOfUpdatedNode() async {
    final wallets = ref
        .read(pWallets)
        .wallets
        .where((e) => e.info.coin == widget.coin);
    final prefs = ref.read(prefsChangeNotifierProvider);

    switch (prefs.syncType) {
      case SyncingType.currentWalletOnly:
        for (final wallet in wallets) {
          if (ref.read(currentWalletIdProvider) == wallet.walletId) {
            unawaited(wallet.updateNode().then((value) => wallet.refresh()));
          } else {
            unawaited(wallet.updateNode());
          }
        }
        break;
      case SyncingType.selectedWalletsAtStartup:
        final List<String> walletIdsToSync = prefs.walletIdsSyncOnStartup;
        for (final wallet in wallets) {
          if (walletIdsToSync.contains(wallet.walletId)) {
            unawaited(wallet.updateNode().then((value) => wallet.refresh()));
          } else {
            unawaited(wallet.updateNode());
          }
        }
        break;
      case SyncingType.allWalletsOnStartup:
        for (final wallet in wallets) {
          unawaited(wallet.updateNode().then((value) => wallet.refresh()));
        }
        break;
    }
  }

  @override
  void initState() {
    isDesktop = Util.isDesktop;
    ref.refresh(nodeFormDataProvider);

    viewType = widget.viewType;
    coin = widget.coin;
    nodeId = widget.nodeId;

    if (nodeId == null) {
      saveEnabled = false;
      testConnectionEnabled = false;
    } else {
      final node = ref
          .read(nodeServiceChangeNotifierProvider)
          .getNodeById(id: nodeId!)!;
      testConnectionEnabled = node.host.isNotEmpty;
      saveEnabled = testConnectionEnabled && node.name.isNotEmpty;
    }

    super.initState();
  }

  @override
  void dispose() {
    super.dispose();
  }

