              value: TorPlainNetworkOption.tor,
              groupValue: netOption,
              onChanged: (value) {
                if (!widget.readOnly) {
                  setState(() => netOption = TorPlainNetworkOption.tor);
                  _updateState();
                }
              },
            ),
          ],
        ),
        const SizedBox(height: 8),
        Row(
          children: [
            RadioTextButton(
              label: l10n.nodeOnlyWithoutTor,
              enabled: !widget.readOnly,
              value: TorPlainNetworkOption.clear,
              groupValue: netOption,
              onChanged: (value) {
                if (!widget.readOnly) {
                  setState(() => netOption = TorPlainNetworkOption.clear);
                  _updateState();
                }
              },
            ),
          ],
        ),
        const SizedBox(height: 8),
        Row(
          children: [
            RadioTextButton(
              label: l10n.nodeBoth,
              enabled: !widget.readOnly,
              value: TorPlainNetworkOption.both,
              groupValue: netOption,
              onChanged: (value) {
                if (!widget.readOnly) {
                  setState(() => netOption = TorPlainNetworkOption.both);
                  _updateState();
                }
              },
            ),
          ],
        ),
      ],
    );
  }
}

class RadioTextButton<T> extends StatelessWidget {
  const RadioTextButton({
    super.key,
    required this.value,
    required this.label,
    required this.groupValue,
    required this.onChanged,
    this.enabled = true,
  });

  final T value;
  final String label;
  final T groupValue;
  final bool enabled;
  final void Function(T) onChanged;

  @override
  Widget build(BuildContext context) {
    return ConditionalParent(
      condition: Util.isDesktop,
      builder: (child) =>
          MouseRegion(cursor: SystemMouseCursors.click, child: child),
      child: GestureDetector(
        onTap: () {
          if (value != groupValue) {
            onChanged.call(value);
          }
        },
        child: Container(
          color: Colors.transparent,
          child: Row(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              SizedBox(
                width: 20,
                height: 20,
                child: Radio<T>(
                  activeColor: Theme.of(context)
                      .extension<StackColors>()!
                      .radioButtonIconEnabled,
                  value: value,
                  groupValue: groupValue,
                  onChanged: !enabled
                      ? null
                      : (_) {
                          if (value != groupValue) {
                            onChanged.call(value);
                          }
                        },
                ),
              ),
              const SizedBox(width: 14),
              Text(label, style: STextStyles.w500_14(context)),
            ],
          ),
        ),
      ),
    );
  }
}
